const families={"炎":1,"氷":2,"水":3,"植物":4,"地":5,"毒":6,"闇":7,"光":8,"風":9,"重力":10,"回復":11,"防御":12,"力場":13,"魔術":14,"信仰":15,"音":16,"言霊":16,"悪":17};
const header="varying vec2 vUv;\nuniform float uTime,uProgress,uSize,uGlow,uSeed,uAspect,uDuration;\nuniform vec2 uResolution;\nuniform vec3 uColor,uCore;\n// @param uNoise 1 0 3 0.05\n// @param uDensity 1 0.1 3 0.05\n// @param uInner 1 0 3 0.05\n// @param uOuter 1 0 3 0.05\nuniform float uNoise;\nuniform float uDensity;\nuniform float uInner;\nuniform float uOuter;\nconst float TAU=6.2831853;\nfloat sat(float x){return clamp(x,0.,1.);}\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7))+uSeed*.013+MAGIC_SEED)*43758.5453);}\nfloat noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(hash(i),hash(i+vec2(1.,0.)),f.x),mix(hash(i+vec2(0.,1.)),hash(i+vec2(1.,1.)),f.x),f.y);}\nfloat fb(vec2 p){return .57*noise(p)+.28*noise(p*2.03)+.15*noise(p*4.13);}\nvec2 dir2(float a){return vec2(cos(a),sin(a));}\nfloat seg(vec2 p,vec2 a,vec2 b){vec2 v=b-a;return length(p-a-v*sat(dot(p-a,v)/max(dot(v,v),.00001)));}\nfloat glw(float d,float w){w=max(w,.003);return uInner*exp(-d/w)+uGlow*uOuter*.70*exp(-d/(w*4.));}\nfloat ball(vec2 p,vec2 c,float r){float d=length(p-c)/max(.01,r);return exp(-d*d*3.)*uInner+exp(-d*d)*uGlow*uOuter*.55;}\nfloat ring(vec2 p,vec2 c,vec2 r,float w){r=max(r,vec2(.015));return glw(abs(length((p-c)/r)-1.)*min(r.x,r.y),w);}\nfloat gate(float q,float a,float b){if(q<=a||q>=b)return 0.;float f=(q-a)/(b-a);return smoothstep(0.,.13,f)*(1.-smoothstep(.55,1.,f));}\nfloat phase(float q,float a,float b){return sat((q-a)/max(.001,b-a));}\nvec3 rainbow(float a){return .55+.45*cos(TAU*(a+vec3(0.,.667,.333)));}\nvec4 light(float z){return vec4(mix(uColor,uCore,smoothstep(.6,1.65,z)),sat(z));}\nvec4 tone(float z,vec3 c){return vec4(mix(c,uCore,smoothstep(.72,1.9,z)),sat(z));}\nvec4 over(vec4 a,vec4 b){float c=b.a+a.a*(1.-b.a);return vec4((b.rgb*b.a+a.rgb*a.a*(1.-b.a))/max(c,.0001),c);}\nfloat shell(vec2 p,vec2 a,vec2 r,float t){vec2 v=(p-a)/max(r,vec2(.02));float n=fb(v*3.4+dir2(TAU*t)*.37);return 1.-smoothstep(.59,1.12,length(v)+(.5-n)*.38*uNoise);}\nfloat spark(vec2 p,vec2 c,float f,float radius,float seed){if(f<=0.||f>=1.)return 0.;float z=0.;for(int j=0;j<20;j++){float k=float(j);if(k>=6.+LEVEL*1.8*uDensity)break;float a=TAU*hash(vec2(k,seed)),r=radius*(.45+.55*hash(vec2(k,seed+1.)))*sqrt(f);vec2 d=dir2(a),v=c+d*r;z+=glw(seg(p,v-d*.045*(1.-f),v),.005)*(.5+.5*hash(vec2(k,seed+3.)));}return z*(1.-smoothstep(.45,1.,f));}\nfloat charge(vec2 p,vec2 c,float f,float r){if(f<=0.||f>=1.)return 0.;float z=0.;for(int i=0;i<8;i++){float k=float(i),a=TAU*hash(vec2(k,31.))+f*.8;z+=ball(p,c+dir2(a)*r*(1.-f)*(.4+.6*hash(vec2(k,19.))),.015);}return z*gate(f,0.,1.)*.7;}\nfloat cone(vec2 p,vec2 a,vec2 b,float w){vec2 v=b-a;float u=sat(dot(p-a,v)/max(dot(v,v),.00001));return glw(length(p-mix(a,b,u)),w*(.3+.7*sin(3.14159*u)));}\nfloat shard(vec2 p,vec2 c,float a,float size){vec2 v=p-c;v=vec2(dot(v,dir2(a)),dot(v,dir2(a+1.5707963)))/max(.02,size);float d=abs(v.x)*.7+abs(v.y)*2.1;return (1.-smoothstep(.79,1.05,d))*.55+glw(abs(d-1.)*size,.0045)*.7;}\nfloat flame(vec2 p,vec2 a,float h,float w,float t){vec2 v=p-a;float y=v.y/max(.05,h);float x=v.x-.07*sin(y*8.-t*TAU*2.)*uNoise;float width=w*max(.08,1.-sat(y))*(.8+.2*sin(y*18.-t*TAU*3.));float d=abs(x)/max(.015,width);float mask=smoothstep(-.10,.06,y)*(1.-smoothstep(.78,1.05,y));return mask*(exp(-d*d*2.)+.35*exp(-d*d*.45))*uInner;}\nfloat loopEnv(float q){return LOOP>0.?1.:smoothstep(0.,.10,q)*(1.-smoothstep(.73,1.,q));}\n";
const bodies={
  "projectile": "float f=phase(q,.13,.76),e=loopEnv(q);vec2 a=vec2(-.68,0.),b=vec2(.63,0.),c=mix(a,b,f);float z=charge(p,a,phase(q,0.,.17),.19);if(q>.13&&q<.80){z+=ball(p,c,.10+LEVEL*.008)*e*POWER;for(int i=0;i<9;i++){float k=float(i),u=sat(f-k*.035);z+=ball(p,mix(a,b,u)+vec2(0.,.04*sin(k*2.+t*12.)),.045)*e*(1.-k/10.)*.6;}}z+=spark(p,b,phase(q,.72,1.),.21+LEVEL*.025,9.)*POWER;return light(z);",
  "contact": "float e=loopEnv(q),d=length(p/vec2(.34,.65));float z=0.;vec4 wash=vec4(uColor,.22*exp(-d*d*2.)*e);for(int i=0;i<9;i++){float k=float(i),a=k*TAU/9.+t*TAU;vec2 c=dir2(a)*vec2(.29,.52);z+=ball(p,c,.048)*e*(.55+.45*sin(t*TAU*4.+k));z+=spark(p,c,fract(q+k*.13),.10,9.+k)*e*.22;}return over(wash,light(z*POWER));",
  "jet": "float f=phase(q,.12,.49),e=loopEnv(q);vec2 a=vec2(-.76,0.),b=vec2(mix(-.76,.78,f),0.);float z=charge(p,a,phase(q,0.,.18),.18);for(int i=0;i<9;i++){float k=float(i),y=(k-4.)*.055*(.4+LEVEL*.16);vec2 end=b+vec2(0.,y);z+=cone(p,a+vec2(0.,y*.15),end,.009+LEVEL*.0015)*e*(.55+.45*sin(t*TAU*3.+k));}for(int j=0;j<15;j++){float k=float(j),u=fract(t*2.+hash(vec2(k,3.)));vec2 c=mix(a,b,u)+vec2(0.,(hash(vec2(k,4.))-.5)*.35*u);z+=ball(p,c,.019)*e*.6;}return light(z*POWER);",
  "beam": "float f=phase(q,.19,.42),e=gate(q,.16,.93);vec2 a=vec2(-.77,0.),b=vec2(.77,0.),tip=mix(a,b,f);float z=charge(p,a,phase(q,0.,.22),.30)+ball(p,a,.11)*gate(q,0.,.40);if(f>0.){z+=glw(seg(p,a,tip),.014+LEVEL*.006)*e*POWER;z+=glw(seg(p,a,tip),.004)*e*.7;for(int i=0;i<4;i++){float k=float(i),y=(k-1.5)*.022*LEVEL;z+=cone(p,a+vec2(0.,y*.2),tip+vec2(0.,y),.006)*e*.65;}z+=ball(p,tip,.065)*e;}z+=spark(p,b,phase(q,.43,1.),.24,22.)*POWER;return light(z);",
  "rain": "float e=loopEnv(q),z=0.;for(int i=0;i<28;i++){float k=float(i);if(k>10.+LEVEL*2.5*uDensity)break;float f=fract(t*2.+hash(vec2(k,3.))),x=(hash(vec2(k,5.))-.5)*1.56;vec2 c=vec2(x,.78-f*1.43);z+=glw(seg(p,c,c+vec2(-.02,-.10)),.007)*e*sin(3.14159*f);z+=ball(p,c,.028)*e*.65;if(f>.84)z+=ring(p,vec2(x,-.65),vec2(.025+(f-.84)*.5,.012+(f-.84)*.11),.005)*e*.6;}return light(z*POWER);",
  "fog": "float e=loopEnv(q),a=0.;for(int i=0;i<5;i++){float k=float(i),ang=k*TAU/5.+t*TAU;vec2 c=dir2(ang)*vec2(.30,.19);a=max(a,shell(p,c,vec2(.38+.025*LEVEL,.25+.02*LEVEL),t+k*.17));}float n=fb(p*6.+dir2(t*TAU)*.4);vec3 c=mix(uColor*.25,uColor,.45+n*.45);return vec4(c,a*e*.75);",
  "ring": "float e=loopEnv(q),z=0.;for(int i=0;i<3;i++){float k=float(i);if(k>1.+step(4.,LEVEL))break;float f=LOOP>0.?fract(t+k*.33):phase(q,.12+k*.12,.99);float r=LOOP>0.?.39+k*.12:.09+.70*f;z+=ring(p,vec2(0.),vec2(r,r*.72),.008+k*.002)*e*(LOOP>0.?.68:sin(3.14159*f))*POWER;}for(int j=0;j<12;j++){float k=float(j),a=k*TAU/12.+t*TAU;z+=ball(p,dir2(a)*vec2(.48,.35),.023)*e*.55;}return light(z);",
  "fall": "float z=0.;for(int i=0;i<7;i++){float k=float(i);if(k>=1.+floor(LEVEL*.62))break;float start=.10+k*.08,f=phase(q,start,start+.46);float x=(hash(vec2(k,11.))-.5)*.92;vec2 a=vec2(x,.78),b=vec2(x,-.63),c=mix(a,b,f*f);if(q>start&&q<start+.46){z+=ball(p,c,.09+LEVEL*.012)*POWER;z+=glw(seg(p,c,c+vec2(.025,.26)),.014)*.7;}float hit=phase(q,start+.44,min(.995,start+.78));z+=spark(p,b,hit,.22+LEVEL*.028,k+9.);z+=ring(p,b,vec2(.03+.34*hit,.02+.10*hit),.009)*sin(3.14159*hit)*POWER;}return light(z);",
  "wall": "float e=loopEnv(q),f=LOOP>0.?1.:sat(q*4.);float y=-.54+1.08*f;float w=smoothstep(-.60,-.49,p.y)*(1.-smoothstep(y-.11,y,p.y))*(1.-smoothstep(.65,.79,abs(p.x)));float n=fb(p*vec2(10.,5.)+dir2(t*TAU)*.5);float z=0.;for(int i=0;i<9;i++){float k=float(i),x=(k-4.)*.17;z+=glw(seg(p,vec2(x,-.53),vec2(x+.02*sin(t*TAU+k),y)),.006)*w*.42;}return over(vec4(uColor*(.38+.55*n),w*e*.38),light(z*e*POWER));",
  "orb": "float e=loopEnv(q),f=LOOP>0.?1.:phase(q,0.,.53);float r=(.16+LEVEL*.032)*(.4+.6*f)*(.94+.06*sin(t*TAU*3.));float d=length(p)/r;float z=(1.-smoothstep(.20,1.,d))*e*POWER+glw(abs(length(p)-r),.009)*e*.62;z+=charge(p,vec2(0.),phase(q,0.,.42),.51);for(int i=0;i<9;i++){float k=float(i),a=k*TAU/9.+t*TAU;z+=ball(p,dir2(a)*(r+.09),.020)*e*.6;}return light(z);",
  "burst": "float f=phase(q,.28,1.),z=charge(p,vec2(0.),phase(q,0.,.29),.43);z+=ball(p,vec2(0.),.12+.15*phase(q,0.,.29))*gate(q,0.,.42);if(f>0.&&f<1.){z+=ball(p,vec2(0.),.24)*gate(f,0.,.5)*POWER*1.7;z+=spark(p,vec2(0.),f,.52+LEVEL*.025,7.)*POWER;for(int i=0;i<3;i++){float k=float(i);if(k>=1.+floor(LEVEL*.35))break;float h=phase(f,k*.12,1.);z+=ring(p,vec2(0.),vec2(.04+.73*h),.009)*sin(3.14159*h)*POWER;}}return light(z);",
  "vortex": "float z=0.,e=loopEnv(q);for(int i=0;i<8;i++){float k=float(i),y=-.65+k*.18,r=(.15+.053*k)*(.65+LEVEL*.065);float a=t*TAU*2.+k*.75;vec2 c=vec2(sin(a)*r,y);z+=ring(p,vec2(0.,y),vec2(r,.055),.007)*(.35+.25*sin(a))*e;z+=ball(p,c,.035)*e*.65;z+=glw(seg(p,c,c+vec2(.11*cos(a),.11)),.006)*e;}return light(z*POWER);",
  "eruption": "float f=phase(q,.12,.65),e=loopEnv(q),z=0.;vec2 c=vec2(0.,-.63);for(int i=0;i<8;i++){float k=float(i);float x=(k-3.5)*.10;float h=(.55+.45*hash(vec2(k,5.)))*1.20*f;z+=flame(p,c+vec2(x*.35,0.),h,.07+LEVEL*.009,t+k*.11)*e;}for(int j=0;j<20;j++){float k=float(j),a=hash(vec2(k,9.)),u=fract(t*1.3+a);vec2 pos=c+vec2((hash(vec2(k,14.))-.5)*1.25*u,4.*u*(1.-u)*(.65+.6*hash(vec2(k,5.))));z+=ball(p,pos,.024)*e*f*sin(3.14159*u);}return light(z*POWER);",
  "wave": "float e=loopEnv(q),z=0.,f=phase(q,.1,.90),x=-.80+1.55*f;for(int i=0;i<4;i++){float k=float(i),xx=x-k*.11;float y=p.y;float curve=xx+.12*cos(y*4.+t*TAU);float edge=glw(abs(p.x-curve),.018+LEVEL*.004);z+=edge*(1.-smoothstep(.36+.04*LEVEL,.76,abs(y)))*e*(1.-k*.16);}for(int j=0;j<14;j++){float k=float(j),y=(hash(vec2(k,4.))-.5)*1.3;z+=ball(p,vec2(x-.10*hash(vec2(k,1.)),y),.024)*e*.6;}return light(z*POWER);",
  "collapse": "float f=phase(q,0.,.65),z=charge(p,vec2(0.),f,.82)*POWER;for(int i=0;i<4;i++){float k=float(i),r=(.72-k*.10)*(1.-f)+.045;z+=ring(p,vec2(0.),vec2(r,r*.68),.008)*gate(q,0.,.78)*POWER;}z+=ball(p,vec2(0.),.095+.06*sin(3.14159*f))*gate(q,.45,.91)*POWER*2.;z+=spark(p,vec2(0.),phase(q,.67,1.),.29,21.)*.9;return light(z);",
  "firestorm": "float z=0.,e=loopEnv(q);for(int i=0;i<7;i++){float k=float(i),x=(k-3.)*.23;float y=-.62+.07*sin(t*TAU+k);float h=.74+.42*(.5+.5*sin(t*TAU*2.+k));z+=flame(p,vec2(x,y),h,.14,t+k*.18)*e;}for(int j=0;j<22;j++){float k=float(j),f=fract(t*2.+hash(vec2(k,5.)));vec2 c=vec2((hash(vec2(k,7.))-.5)*1.45+.12*sin(f*TAU),-.65+1.43*f);z+=ball(p,c,.025)*sin(3.14159*f)*e*.75;}return light(z*POWER);",
  "nova": "float f=phase(q,.39,1.),z=charge(p,vec2(0.),phase(q,0.,.41),.76)*POWER;z+=ball(p,vec2(0.),.06+.18*phase(q,0.,.4))*gate(q,0.,.49)*POWER;if(f>0.&&f<1.){z+=ball(p,vec2(0.),.38)*gate(f,0.,.45)*POWER*2.;for(int i=0;i<3;i++){float k=float(i),h=phase(f,k*.15,1.);z+=ring(p,vec2(0.),vec2(.04+.94*h),.013)*sin(3.14159*h)*POWER;}z+=spark(p,vec2(0.),f,.88,7.)*POWER;}return light(z);",
  "aura": "float e=loopEnv(q),d=length(p/vec2(.46,.70)),z=glw(abs(d-1.)*.4,.009)*.28*e;vec4 base=vec4(uColor,.18*exp(-d*d*1.5)*e);for(int i=0;i<16;i++){float k=float(i),f=fract(t+hash(vec2(k,8.))),x=.39*sin(k*2.4+t*TAU);vec2 c=vec2(x,-.62+1.24*f);z+=ball(p,c,.027)*e*sin(3.14159*f)*.65;}return over(base,light(z*POWER));",
  "shield": "vec2 r=vec2(.53,.72);float d=length(p/r),a=atan(p.y/r.y,p.x/r.x),e=loopEnv(q);vec4 base=vec4(uColor,(1.-smoothstep(.93,1.06,d))*(.07+.10*pow(sat(d),4.))*e);float z=ring(p,vec2(0.),r,.010)*e*(.8+.2*sin(a*5.-t*TAU*2.));for(int i=0;i<10;i++){float k=float(i),ang=k*TAU/10.+t*TAU;z+=ball(p,dir2(ang)*r,.033)*e*.75;z+=glw(seg(p,dir2(ang)*r,dir2(ang+.24)*r),.006)*e*.55;}return over(base,light(z*POWER));",
  "platform": "float e=loopEnv(q),d=length(p/vec2(.72,.22));float z=ring(p,vec2(0.),vec2(.72,.22),.009)*e+ring(p,vec2(0.),vec2(.57,.16),.005)*e*.55;return over(vec4(uColor,(1.-smoothstep(.9,1.03,d))*.18*e),light(z));",
  "cage": "float e=loopEnv(q),z=0.;for(int i=0;i<8;i++){float k=float(i),a=k*TAU/8.+.15*t;float x=.57*cos(a),y=.17*sin(a);z+=glw(seg(p,vec2(x,-.60+y),vec2(x,.60+y)),.009)*e*.8;}z+=ring(p,vec2(0.,-.60),vec2(.57,.15),.008)*e+ring(p,vec2(0.,.60),vec2(.57,.15),.008)*e;return light(z*POWER);",
  "dissolve": "float e=loopEnv(q),z=0.;for(int i=0;i<20;i++){float k=float(i),a=k*TAU/20.+t;vec2 c=dir2(a)*(.17+.59*q)*(.55+.45*hash(vec2(k,9.)));z+=ball(p,c,.025)*e;}z+=ring(p,vec2(0.),vec2(.22+.47*q),.006)*e*.7;return light(z);",
  "lift": "float e=loopEnv(q),z=ring(p,vec2(0.,-.52),vec2(.53,.16),.009)*e;for(int i=0;i<18;i++){float k=float(i),f=fract(t+hash(vec2(k,7.))),x=.43*cos(k*2.2+t*TAU);z+=glw(seg(p,vec2(x,-.59+f*1.18),vec2(x,-.46+f*1.18)),.007)*e*sin(3.14159*f);}return light(z*POWER);",
  "warp": "float e=loopEnv(q),z=0.;for(int i=0;i<5;i++){float k=float(i),f=fract(t+k*.20),r=.09+.62*(1.-f);vec2 v=p+vec2(.08*sin(p.y*9.+t*TAU),.04*cos(p.x*8.+t*TAU));z+=ring(v,vec2(0.),vec2(r,r*.8),.007)*sin(3.14159*f)*e;}return light(z*POWER);",
  "vine": "float z=0.,g=phase(q,0.,.56),e=loopEnv(q);for(int i=0;i<5;i++){float k=float(i),x=(k-2.)*.24;vec2 a=vec2(x,-.67);for(int j=0;j<7;j++){float h=float(j),u=min(g,(h+1.)/7.);if(u>h/7.){vec2 b=vec2(x+.15*sin(u*7.+k),-.67+1.24*u);z+=glw(seg(p,a,b),.020)*e*.8;z+=shard(p,b+vec2(.045*sin(k+h),.02),k+h,.07)*e*.55;a=b;}}}return tone(z*POWER,mix(uColor,vec3(.13,.48,.08),.2));",
  "heal": "float e=loopEnv(q),z=0.;for(int i=0;i<18;i++){float k=float(i),f=fract(t+hash(vec2(k,8.))),a=k*2.4+f*TAU;vec2 c=vec2(.39*cos(a),-.62+1.22*f);z+=ball(p,c,.028+LEVEL*.002)*sin(3.14159*f)*e;}for(int j=0;j<2;j++){float k=float(j),f=fract(t+k*.5);z+=ring(p,vec2(0.,-.45+f*.86),vec2(.38+.14*f,.11),.006)*sin(3.14159*f)*e;}return over(vec4(uColor,.12*exp(-dot(p,p)*4.)*e),light(z*POWER));",
  "swarm": "float e=loopEnv(q),z=0.;for(int i=0;i<24;i++){float k=float(i);if(k>8.+LEVEL*2.*uDensity)break;vec2 a=vec2(hash(vec2(k,7.)),hash(vec2(k,13.)))*1.3-.65;vec2 c=a+dir2(t*TAU+k)*.085;z+=ball(p,c,.023)*e*(.45+.55*pow(.5+.5*sin(t*TAU*3.+k),3.));}return light(z*POWER);",
  "growth": "float g=LOOP>0.?1.:phase(q,0.,.58),e=loopEnv(q),z=0.;vec2 a=vec2(0.,-.64),b=vec2(0.,-.64+1.18*g);z+=glw(seg(p,a,b),.027)*e;for(int i=0;i<7;i++){float k=float(i),u=(k+1.)/8.;if(g>u){vec2 a=vec2(0.,-.64+1.18*u),end=a+vec2((mod(k,2.)*2.-1.)*.34,.20)*sat((g-u)*4.);z+=glw(seg(p,a,end),.012)*e+shard(p,end,k*.8,.11)*e;}}return tone(z*POWER,uColor);",
  "roots": "float e=loopEnv(q),z=0.;for(int i=0;i<8;i++){float k=float(i),a=k*TAU/8.,r=.23+.39*hash(vec2(k,6.));vec2 b=dir2(a)*vec2(r,r*.48),c=dir2(a+.22)*vec2(.82,.42);z+=glw(seg(p,vec2(0.),b),.012)*e+glw(seg(p,b,c),.009)*e*.8;z+=ball(p,mix(b,c,fract(t+k*.1)),.024)*e;}return light(z);",
  "tree": "float e=loopEnv(q),g=LOOP>0.?1.:phase(q,0.,.60),z=0.;vec2 a=vec2(0.,-.66),b=vec2(0.,-.66+1.17*g);float wood=glw(seg(p,a,b),.045)*e;for(int i=0;i<7;i++){float k=float(i),u=.36+k*.075;if(g>u){vec2 a=vec2(0.,-.66+1.17*u),end=a+vec2((mod(k,2.)*2.-1.)*(.36-.035*k),.18)*sat((g-u)*5.);wood+=glw(seg(p,a,end),.018)*e;z+=shell(p,end,vec2(.23,.17),t+k*.13)*e*.65;}}return over(tone(wood*.85,vec3(.46,.28,.12)),tone(z,uColor));",
  "forest": "float e=loopEnv(q),g=LOOP>0.?1.:phase(q,0.,.63),wood=0.,z=0.;for(int i=0;i<5;i++){float k=float(i),x=(k-2.)*.29,f=sat(g*1.5-k*.085);vec2 a=vec2(x,-.65),b=a+vec2(0.,(.66+.25*hash(vec2(k,7.)))*f);wood+=glw(seg(p,a,b),.025)*e;z+=shell(p,b,vec2(.20,.23)*max(.1,f),t+k*.17)*e*f;}return over(tone(wood*.8,vec3(.45,.28,.12)),tone(z,uColor));",
  "crystal": "float e=loopEnv(q),f=LOOP>0.?1.:phase(q,.03,.65),z=0.;for(int i=0;i<9;i++){float k=float(i);if(k>3.+LEVEL*.85)break;float a=k*TAU/(4.+floor(LEVEL*.85));vec2 c=dir2(a)*(.18+.20*f)*f;z+=shard(p,c,a,.18*f)*e;z+=ball(p,c,.025)*e*.4;}return light(z*POWER);",
  "icicle": "float e=loopEnv(q),f=phase(q,.04,.62),z=0.;for(int i=0;i<5;i++){float k=float(i);if(k>1.+floor(LEVEL*.55))break;float x=(k-2.)*.23;vec2 a=vec2(x,.65),b=vec2(x,-.57);vec2 c=mix(a,b,f*.52);vec2 v=p-c;float yy=(v.y+.6*f)/max(.02,1.1*f);float w=.12*(1.-sat(yy));float d=abs(v.x)/max(.015,w);float m=smoothstep(0.,.07,yy)*(1.-smoothstep(.90,1.0,yy));z+=(1.-smoothstep(.72,1.,d))*m*e+glw(abs(abs(v.x)-w),.004)*m*e*.7;}return light(z*POWER);",
  "crack": "float f=phase(q,.06,.69),e=loopEnv(q),z=0.;for(int i=0;i<8;i++){float k=float(i),a=k*TAU/8.+.2*hash(vec2(k,6.));vec2 d=dir2(a)*vec2(1.,.56),m=d*.34*f,b=d*.80*f+vec2(.05*sin(k),.02);z+=glw(seg(p,vec2(0.),m),.009)*e;z+=glw(seg(p,m,b),.006)*e;z+=glw(seg(p,m,m+dir2(a+.8)*.20*f),.004)*e*.8;}return over(vec4(vec3(.16,.08,.05),z*e*.45),tone(z*.72,uColor));",
  "eclipse": "float e=loopEnv(q),f=LOOP>0.?1.:phase(q,0.,.65);float r=.18+.38*f,d=length(p);float dark=1.-smoothstep(r*.9,r*1.03,d);float z=glw(abs(d-r),.008)*e*(.65+.35*sin(t*TAU));return over(vec4(vec3(.025,.018,.055),dark*e*.92),tone(z*.75,uColor));",
  "whip": "float f=phase(q,.08,.72),e=loopEnv(q),z=0.;vec2 a=vec2(-.75,-.2);for(int i=0;i<18;i++){float k=float(i),u=min((k+1.)/18.,f);if(u>k/18.){vec2 b=vec2(-.75+1.43*u,-.2+.47*sin(u*3.14159)*sin(t*TAU*1.7));z+=glw(seg(p,a,b),.014)*e*POWER;a=b;}}z+=ball(p,a,.049)*e;return light(z);",
  "distort": "float e=loopEnv(q),z=0.;for(int i=0;i<4;i++){float k=float(i),r=.19+k*.145;vec2 w=p+vec2(.08*sin(p.y*7.+t*TAU+k),.055*sin(p.x*9.+t*TAU));z+=ring(w,vec2(0.),vec2(r,r*.78),.007)*e*(.6+.3*sin(t*TAU+k));}return light(z*POWER);",
  "blackhole": "float e=loopEnv(q),f=phase(q,0.,.52),r=.16+.17*f,d=length(p),a=atan(p.y,p.x);float z=glw(abs(d-r),.013)*POWER*e;z+=glw(abs(d-(r+.11+.025*sin(a*5.-t*TAU*3.))),.009)*e;for(int i=0;i<16;i++){float k=float(i),u=fract(t*1.5+hash(vec2(k,4.)));vec2 c=dir2(k*2.4+u*TAU)*mix(.78,r,u);z+=ball(p,c,.018)*sin(3.14159*u)*e;}return over(vec4(vec3(.015,.009,.028),(1.-smoothstep(r*.9,r*1.04,d))*e),tone(z,uColor));",
  "resonance": "float e=loopEnv(q),z=0.;for(int i=0;i<5;i++){float k=float(i),f=fract(t+k*.2),r=.06+.77*f;z+=ring(p,vec2(0.),vec2(r,r*.74),.007)*sin(3.14159*f)*e*POWER;}return light(z);",
  "shade": "float e=loopEnv(q),f=phase(q,0.,.55);vec2 c=vec2(.31*f,0.);float a=shell(p,c,vec2(.26,.67),t);float z=glw(abs(length((p-c)/vec2(.26,.67))-1.)*.26,.007)*e;return over(vec4(vec3(.04,.025,.09),a*.80*e),tone(z*.38,uColor));",
  "nebula": "float e=loopEnv(q),a=0.,z=0.;for(int i=0;i<6;i++){float k=float(i),ang=k*TAU/6.+t*TAU;vec2 c=dir2(ang)*vec2(.33,.23);a=max(a,shell(p,c,vec2(.38,.32),t+k*.2));z+=ball(p,c,.11)*.11*e;}return over(vec4(mix(vec3(.025,.018,.045),uColor*.42,fb(p*6.+dir2(t*TAU))),a*.87*e),tone(z,uColor));",
  "flash": "float e=gate(q,0.,.80),z=ball(p,vec2(0.),.24)*e*POWER;for(int i=0;i<8;i++){float k=float(i),a=k*TAU/8.;z+=glw(seg(p,vec2(0.),dir2(a)*(.22+.31*hash(vec2(k,7.)))),.008)*e*.8;}return light(z);",
  "prism": "float e=loopEnv(q),f=phase(q,.12,.60);vec2 a=vec2(-.74,0.),c=vec2(-.05,0.);vec4 outColor=light(glw(seg(p,a,mix(a,c,sat(f*2.))),.014)*e);for(int i=0;i<7;i++){float k=float(i),g=sat(f*2.-1.);vec2 b=vec2(.72,(k-3.)*.20);if(g>0.)outColor=over(outColor,tone(glw(seg(p,c,mix(c,b,g)),.010)*e,rainbow(k/7.)));}return outColor;",
  "sundog": "float e=loopEnv(q),z=ball(p,vec2(0.),.17)*e*POWER;z+=ball(p,vec2(-.49,0.),.095)*e+ball(p,vec2(.49,0.),.095)*e;z+=ring(p,vec2(0.),vec2(.49,.49),.007)*e*.44;return light(z);",
  "iridescent": "float e=loopEnv(q),d=shell(p,vec2(0.),vec2(.73,.40),t);vec3 c=rainbow(p.x*.40+p.y*.18+t)*.65+.30;return vec4(c,d*e*.75);",
  "pillar": "float e=loopEnv(q),f=LOOP>0.?1.:phase(q,0.,.48),z=glw(seg(p,vec2(0.,-.66),vec2(0.,-.66+1.38*f)),.035+LEVEL*.008)*e*POWER;for(int i=0;i<12;i++){float k=float(i),u=fract(t+hash(vec2(k,8.)));vec2 c=vec2(.14*sin(k*2.3+u*TAU),-.65+u*1.33*f);z+=ball(p,c,.021)*e*sin(3.14159*u);}return light(z);",
  "mirage": "float e=loopEnv(q),z=0.;for(int i=0;i<5;i++){float k=float(i),y=(k-2.)*.14+.04*sin(p.x*8.+t*TAU+k);z+=glw(abs(p.y-y),.007)*(1.-smoothstep(.55,.79,abs(p.x)))*e*.7;}return tone(z,uColor);",
  "luminouscloud": "float e=loopEnv(q),a=0.;for(int i=0;i<4;i++){float k=float(i);a=max(a,shell(p,vec2((k-1.5)*.27,.04*sin(t*TAU+k)),vec2(.35,.24),t+k*.2));}float n=fb(p*8.+dir2(t*TAU));return vec4(mix(uColor,uCore,n*.66),a*e*.82);",
  "aurora": "float e=loopEnv(q);vec4 result=vec4(0.);for(int i=0;i<4;i++){float k=float(i),y=.14*k-.22+.20*sin(p.x*4.+t*TAU+k*.7);float a=exp(-pow((p.y-y)*7.,2.))*(1.-smoothstep(.60,.88,abs(p.x)))*e*.55;result=over(result,vec4(rainbow(k*.15+p.x*.2+t*.15),a));}return result;",
  "cleanse": "float e=loopEnv(q),z=0.;for(int i=0;i<16;i++){float k=float(i),a=k*TAU/16.,r=.13+.48*q;z+=ball(p,dir2(a)*vec2(r,r*.75),.022)*e;}z+=ring(p,vec2(0.),vec2(.10+.65*q,.075+.49*q),.008)*e*POWER;return light(z);",
  "revive": "float e=loopEnv(q),z=0.,f=phase(q,0.,.63);z+=glw(seg(p,vec2(0.,-.63),vec2(0.,-.63+1.37*f)),.09)*e*POWER;for(int i=0;i<3;i++){float k=float(i),u=fract(t+k*.33);z+=ring(p,vec2(0.,-.56+u*1.14),vec2(.42+.10*u,.13),.008)*e*sin(3.14159*u);}for(int j=0;j<16;j++){float k=float(j),u=fract(t+hash(vec2(k,4.)));z+=ball(p,vec2(.36*sin(k*2.4+u*TAU),-.63+u*1.27),.024)*e*sin(3.14159*u);}return light(z);",
  "downburst": "float f=phase(q,.09,.55),e=loopEnv(q),z=0.;for(int i=0;i<7;i++){float k=float(i),x=(k-3.)*.08;z+=glw(seg(p,vec2(x,.74),vec2(x,-.59*f+.74*(1.-f))),.010)*e*.85;}float h=phase(q,.48,1.);z+=ring(p,vec2(0.,-.60),vec2(.04+.77*h,.02+.18*h),.010)*sin(3.14159*h)*POWER;z+=spark(p,vec2(0.,-.60),h,.65,8.)*.7;return light(z);",
  "stone": "float e=loopEnv(q),f=phase(q,0.,.58),z=0.;for(int i=0;i<5;i++){float k=float(i),x=(k-2.)*.22;vec2 c=vec2(x,-.62+(.40+.23*hash(vec2(k,4.)))*f);z+=shard(p,c,k*.8,.21*f)*e;}return tone(z,uColor);",
  "slash": "float e=loopEnv(q),f=phase(q,.12,.68),z=0.;vec2 c=vec2(-.60+1.20*f,0.);float a=atan(p.y-c.y,p.x-c.x);z+=ring(p,c,vec2(.32,.47),.014)*e*(.4+.6*smoothstep(-1.,.1,cos(a)));z+=spark(p,c,phase(q,.55,1.),.25,9.)*.6;return light(z*POWER);"
};
const decoration="\nvec4 decorate(vec2 p,float t,float q,vec4 base){float e=loopEnv(q),z=0.;\n if(FAMILY==1.){\n  for(int j=0;j<9;j++){float k=float(j),f=fract(t*2.+hash(vec2(k,31.)));vec2 c=vec2((hash(vec2(k,9.))-.5)*1.2,-.58+1.16*f);z+=ball(p,c,.015)*sin(3.14159*f)*e*.45;}\n }else if(FAMILY==2.||FAMILY==5.){\n  for(int j=0;j<7;j++){float k=float(j),f=fract(t+hash(vec2(k,5.)));vec2 c=vec2((hash(vec2(k,12.))-.5)*1.1,-.45+.9*f);z+=shard(p,c,k+t,.028)*sin(3.14159*f)*e*.35;}\n }else if(FAMILY==3.||FAMILY==9.||FAMILY==16.){\n  for(int j=0;j<4;j++){float k=float(j),y=(k-1.5)*.22+.035*sin(p.x*9.+t*TAU+k);z+=glw(abs(p.y-y),.0035)*(1.-smoothstep(.25,.75,abs(p.x)))*e*.11;}\n }else if(FAMILY==4.||FAMILY==6.||FAMILY==11.){\n  for(int j=0;j<8;j++){float k=float(j),f=fract(t+hash(vec2(k,19.)));z+=ball(p,vec2(.42*sin(k*2.4+f*TAU),-.53+1.06*f),.018)*sin(3.14159*f)*e*.45;}\n }\n // Decoration remains inside the visible effect rather than adding unrelated particles to the scene.\n return over(base,tone(z*sat(base.a*3.),uColor));}\n";
// Individually authored fire effects; base templates remain for unreviewed families.
